mapper.select:
SELECT t.id, t.updated_at,
        ARRAY(SELECT p.parent_id FROM entity_type_parents p WHERE p.child_id = t.id) AS parents
 FROM entity_types t WHERE t.kb_id = #{kbId}

SELECT id FROM entity_types WHERE kb_id = #{kbId}
  AND id = ANY(#{candidates,typeHandler=tech.seexun.jknow.store.typehandler.UuidArrayTypeHandler}::uuid[])
 ORDER BY id FOR SHARE

mapper.update:
UPDATE entities
    SET type_id = #{typeId}, type_source = 'aligned', proposed_type = NULL, updated_at = now()
  WHERE kb_id = #{kbId} AND merged_into IS NULL AND type_source <> 'human'
    AND specific_type IS NOT NULL
    AND lower(btrim(regexp_replace(specific_type, '\s+', ' ', 'g'))) = #{kindWord}
    AND type_id IS DISTINCT FROM #{typeId}
